namespace sv_d88db40dddd4424783817203fc1fa821.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <li class="step-item @stepClass">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">✓</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "step-current";
        if (CompletedSteps.Contains(step)) return "step-completed";
        return "step-future";
    }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" value="@FullName"
               @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" value="@Email"
               @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" value="@Phone"
               @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" class="form-control" rows="3"
                  @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Address</textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="OnRemove.InvokeAsync">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Company"
               @oninput="e => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Title"
               @oninput="e => TitleChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => StartDateChanged.InvokeAsync(DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => EndDateChanged.InvokeAsync(string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!))" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => IsCurrentChanged.InvokeAsync((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description"
                  @oninput="e => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Description</textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       CompanyChanged="e => UpdateEntry(index, entry with { Company = e })"
                       TitleChanged="e => UpdateEntry(index, entry with { Title = e })"
                       StartDateChanged="e => UpdateEntry(index, entry with { StartDate = e })"
                       EndDateChanged="e => UpdateEntry(index, entry with { EndDate = e })"
                       IsCurrentChanged="e => UpdateEntry(index, entry with { IsCurrent = e, EndDate = e ? null : entry.EndDate })"
                       DescriptionChanged="e => UpdateEntry(index, entry with { Description = e })"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
        EntriesChanged.InvokeAsync(Entries);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        EntriesChanged.InvokeAsync(Entries);
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        EntriesChanged.InvokeAsync(Entries);
    }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="OnRemove.InvokeAsync">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" class="form-control" value="@Name"
                   @oninput="e => NameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>

        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" class="form-control" value="@Relationship"
                   @oninput="e => RelationshipChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Email"
                   @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>

        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Phone"
                   @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> NameChanged { get; set; }
    [Parameter] public EventCallback<string> RelationshipChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <ReferenceForm Index="index"
                       Name="@reference.Name"
                       Relationship="@reference.Relationship"
                       Email="@reference.Email"
                       Phone="@reference.Phone"
                       CanRemove="@(References.Count > 2)"
                       NameChanged="e => UpdateReference(index, reference with { Name = e })"
                       RelationshipChanged="e => UpdateReference(index, reference with { Relationship = e })"
                       EmailChanged="e => UpdateReference(index, reference with { Email = e })"
                       PhoneChanged="e => UpdateReference(index, reference with { Phone = e })"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void UpdateReference(int index, ReferenceModel updated)
    {
        References[index] = updated;
        ReferencesChanged.InvokeAsync(References);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
            ReferencesChanged.InvokeAsync(References);
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
            ReferencesChanged.InvokeAsync(References);
        }
    }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea" rows="12"
                  maxlength="@MaxLength"
                  @oninput="e => CoverLetterChanged.InvokeAsync(e.Value?.ToString() ?? "")">@CoverLetter</textarea>
        <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    <div class="review-section">
        <div class="review-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl class="review-details">
            <dt>Full Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="review-dates">
                    @entry.StartDate.ToString("MMM yyyy") —
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="review-reference">
                <strong>@reference.Name</strong> (@reference.Relationship)
                <div>@reference.Email · @reference.Phone</div>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <div class="review-cover-letter">@CoverLetter</div>
    </div>

    @if (!string.IsNullOrEmpty(SubmitError))
    {
        <div class="validation-error">@SubmitError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary btn-submit" @onclick="OnSubmit.InvokeAsync" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? SubmitError { get; set; }

    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
}

namespace sv_d88db40dddd4424783817203fc1fa821.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
