@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea" rows="12"
                  maxlength="@MaxLength"
                  @oninput="e => CoverLetterChanged.InvokeAsync(e.Value?.ToString() ?? "")">@CoverLetter</textarea>
        <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    <div class="review-section">
        <div class="review-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl class="review-details">
            <dt>Full Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="review-dates">
                    @entry.StartDate.ToString("MMM yyyy") —
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="review-reference">
                <strong>@reference.Name</strong> (@reference.Relationship)
                <div>@reference.Email · @reference.Phone</div>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <div class="review-cover-letter">@CoverLetter</div>
    </div>

    @if (!string.IsNullOrEmpty(SubmitError))
    {
        <div class="validation-error">@SubmitError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary btn-submit" @onclick="OnSubmit.InvokeAsync" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? SubmitError { get; set; }

    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
}

