.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: "";
    position: absolute;
    top: 18px;
    left: 10%;
    right: 10%;
    height: 2px;
    background: #e0e0e0;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0;
    gap: 0.5rem;
}

.step-completed .step-button {
    cursor: pointer;
}

.step-icon {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    background: #e0e0e0;
    color: #999;
}

.step-current .step-icon {
    background: #4361ee;
    color: white;
}

.step-completed .step-icon {
    background: #2ecc71;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #999;
    max-width: 80px;
}

.step-current .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-completed .step-label {
    color: #2ecc71;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 0.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #333;
    font-size: 0.875rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 0.9375rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: 400 !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.625rem 1.25rem;
    border-radius: 4px;
    font-size: 0.9375rem;
    font-weight: 500;
    border: none;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-outline {
    background: white;
    color: #4361ee;
    border: 1px solid #4361ee;
}

.btn-outline:hover {
    background: #f0f4ff;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger-sm {
    background: none;
    border: 1px solid #e74c3c;
    color: #e74c3c;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8125rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #fdf0ef;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3651d4;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
.validation-error {
    background: #fdf0ef;
    border: 1px solid #f5c6cb;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #e74c3c;
    font-size: 0.8125rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #eee;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #333;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.8125rem;
    color: #666;
    margin-top: 0.375rem;
}

.char-count.over-limit {
    color: #e74c3c;
    font-weight: 600;
}

/* Review Step */
.review-section {
    border: 1px solid #eee;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

.review-details {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.375rem 1rem;
    margin: 0;
}

.review-details dt {
    font-weight: 500;
    color: #666;
    font-size: 0.875rem;
}

.review-details dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.review-dates {
    font-size: 0.8125rem;
    color: #666;
    margin-top: 0.25rem;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.875rem;
    line-height: 1.5;
    color: #333;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #2ecc71;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.submission-confirmation h2 {
    color: #2ecc71;
    margin-bottom: 0.5rem;
}

.application-id {
    font-size: 1.5rem;
    font-weight: 700;
    color: #4361ee;
    margin: 1rem 0;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-label {
        font-size: 0.625rem;
        max-width: 60px;
    }

    .step-icon {
        width: 28px;
        height: 28px;
        font-size: 0.75rem;
    }
}

