    color: #e74c3c;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8125rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #fdf0ef;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3651d4;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

