.validation-error {
    background: #fdf0ef;
    border: 1px solid #f5c6cb;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #e74c3c;
    font-size: 0.8125rem;
    margin-top: 0.25rem;
    display: block;
}

