.review-section {
    border: 1px solid #eee;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

.review-details {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.375rem 1rem;
    margin: 0;
}

.review-details dt {
    font-weight: 500;
    color: #666;
    font-size: 0.875rem;
}

.review-details dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.review-dates {
    font-size: 0.8125rem;
    color: #666;
    margin-top: 0.25rem;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.875rem;
    line-height: 1.5;
    color: #333;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #2ecc71;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.submission-confirmation h2 {
    color: #2ecc71;
    margin-bottom: 0.5rem;
}

.application-id {
    font-size: 1.5rem;
    font-weight: 700;
    color: #4361ee;
    margin: 1rem 0;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-label {
        font-size: 0.625rem;
        max-width: 60px;
    }

    .step-icon {
        width: 28px;
        height: 28px;
        font-size: 0.75rem;
    }
}
