@page "/apply"
@namespace sv_d88db40dddd4424783817203fc1fa821.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_d88db40dddd4424783817203fc1fa821.Models

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    @if (_submitted)
    {
        <div class="submission-confirmation">
            <div class="confirmation-icon">✓</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@_applicationId</div>
            <p>We will be in touch soon.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  ValidationError="@_validationError"
                                  EmailError="@_emailError"
                                  IsValidating="@_isValidating"
                                  FullNameChanged="v => _fullName = v"
                                  EmailChanged="v => { _email = v; _emailError = null; }"
                                  PhoneChanged="v => _phone = v"
                                  AddressChanged="v => _address = v"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 ValidationError="@_validationError"
                                 EntriesChanged="v => _workEntries = v"
                                 OnBack="() => GoToStep(0)"
                                 OnNext="HandleWorkHistoryNext" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                ValidationError="@_validationError"
                                ReferencesChanged="v => _references = v"
                                OnBack="() => GoToStep(1)"
                                OnNext="HandleReferencesNext" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 ValidationError="@_validationError"
                                 CoverLetterChanged="v => _coverLetter = v"
                                 OnBack="() => GoToStep(2)"
                                 OnNext="HandleCoverLetterNext" />
                break;

            case 4:
                <ReviewStep FullName="@_fullName"
                            Email="@_email"
                            Phone="@_phone"
                            Address="@_address"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            IsSubmitting="_isSubmitting"
                            SubmitError="@_submitError"
                            OnEditStep="GoToStep"
                            OnBack="() => GoToStep(3)"
                            OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int _currentStep;
    private HashSet<int> _completedSteps = new();
    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _submitError;

    // Step 1 - Personal Info
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 - Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep || _completedSteps.Contains(step))
        {
            _validationError = null;
            _currentStep = step;
        }
    }

    private async Task HandlePersonalInfoNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _validationError = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!emailValid)
            {
                _emailError = "This email address is not valid.";
                _isValidating = false;
                return;
            }
        }
        finally
        {
            _isValidating = false;
        }

        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext()
    {
        _validationError = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Please fill in company name and job title for all positions.";
                return;
            }
        }

        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext()
    {
        _validationError = null;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                _validationError = "Please fill in all fields for each reference.";
                return;
            }
        }

        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _validationError = "Please write a cover letter.";
            return;
        }

        if (_coverLetter.Length > 2000)
        {
            _validationError = "Cover letter must be 2000 characters or fewer.";
            return;
        }

        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        _submitError = null;
        _isSubmitting = true;

        try
        {
            var workEntries = _workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();

            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(workEntries),
                references,
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _completedSteps.Add(4);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"An error occurred while submitting: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

