+                _validationError = "Please fill in company name and job title for all positions.";
+                return;
+            }
+        }
+
+        _completedSteps.Add(1);
+        _currentStep = 2;
+    }
+
+    private void HandleReferencesNext()
+    {
+        _validationError = null;
+
+        foreach (var reference in _references)
+        {
+            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
+                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
+            {
+                _validationError = "Please fill in all fields for each reference.";
+                return;
+            }
+        }
+
+        _completedSteps.Add(2);
+        _currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext()
+    {
+        _validationError = null;
+
+        if (string.IsNullOrWhiteSpace(_coverLetter))
+        {
+            _validationError = "Please write a cover letter.";
+            return;
+        }
+
+        if (_coverLetter.Length > 2000)
+        {
+            _validationError = "Cover letter must be 2000 characters or fewer.";
+            return;
+        }
+
+        _completedSteps.Add(3);
+        _currentStep = 4;
+    }
+
+    private async Task HandleSubmit()
+    {
+        _submitError = null;
+        _isSubmitting = true;
+
+        try
+        {
+            var workEntries = _workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
+
+            var references = _references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+            var application = new JobApplication(
+                new PersonalInfo(_fullName, _email, _phone, _address),
+                new WorkHistory(workEntries),
+                references,
+                _coverLetter
+            );
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _completedSteps.Add(4);
+            _submitted = true;
+        }
+        catch (Exception ex)
+        {
+            _submitError = $"An error occurred while submitting: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+}
