    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => StartDateChanged.InvokeAsync(DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => EndDateChanged.InvokeAsync(string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!))" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => IsCurrentChanged.InvokeAsync((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description"
                  @oninput="e => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Description</textarea>
    </div>
