        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="HandleStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd"))"
                   disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="HandleIsCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3"
                  @oninput="HandleDescriptionInput">@Description</textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private Task HandleCompanyInput(ChangeEventArgs e) => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    private Task HandleTitleInput(ChangeEventArgs e) => TitleChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    private Task HandleDescriptionInput(ChangeEventArgs e) => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    private Task HandleRemove() => OnRemove.InvokeAsync();

    private Task HandleStartDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        return StartDateChanged.InvokeAsync(date);
    }

    private Task HandleEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        DateTime? date = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        return EndDateChanged.InvokeAsync(date);
    }

    private Task HandleIsCurrentChange(ChangeEventArgs e)
    {
        return IsCurrentChanged.InvokeAsync((bool)(e.Value ?? false));
    }
}

